// Browser half entry for dsh-next-message-predictor.
//
// Registers the ghost overlay into the session-scoped
// `conversation.input.overlay` list slot, contributes its own Settings page via
// `settings.section`, offers the same page as a global panel with an optional
// entry in the left sidebar (`main` + `sidebar.panellist`), owns the page-level
// focus/visibility signals, and exposes a small debug surface for manual
// verification.
//
// The bundle is generated by scripts/build-client.mjs from src/shared/* and
// src/client/* wrapped in the host's ModuleLoader factory; this file must be a
// plain function body (no imports) after concatenation.

function createClient(react) {
  return {
    inject: ['slots', 'locale', 'connection'],
    apply(ctx) {
      const slots = typeof ctx.get === 'function' ? ctx.get('slots') : undefined
      const locale = typeof ctx.get === 'function' ? ctx.get('locale') : undefined
      if (slots === undefined || slots === null || locale === undefined || locale === null) {
        console.warn('[next-message-predictor] client services missing; overlay not registered')
        return
      }

      // DSH gets the dictionaries of the languages it offers itself. The texts
      // on screen come from this plugin's own translate function (below), which
      // also knows the language chosen in this plugin's Settings.
      ctx.effect(() => locale.register(NS, nmpHostDictionaries()), 'next-message-predictor: locale')

      const runtime = createClientRuntime({ rpc: createRouteRpc() })

      /** The language DSH is showing, read back through the probe key; '' when unknown. */
      const hostLanguage = () => {
        try {
          const translate = typeof locale.bind === 'function' ? locale.bind(NS) : undefined
          if (typeof translate === 'function') {
            const id = translate(NMP_LANGUAGE_PROBE_KEY)
            if (nmpIsLanguage(id)) return id
          }
        } catch {
          /* fall through to the page and browser language */
        }
        return ''
      }
      const pageLanguage = () => {
        try {
          return document.documentElement.lang
        } catch {
          return ''
        }
      }
      const browserLanguage = () => {
        try {
          return navigator.language
        } catch {
          return ''
        }
      }
      // Until the Host has answered, the last known choice is used so the page
      // does not start in one language and switch to another.
      let languageMemo = nmpReadLanguageMemo()
      const languageSetting = () => {
        const state = runtime.configStore.getSnapshot()
        return state.ready === true && state.hostError === '' ? state.config.language : languageMemo
      }
      const currentLanguage = () => {
        const setting = languageSetting()
        return setting === LANGUAGE_AUTO
          ? nmpResolveLanguage(setting, [hostLanguage(), pageLanguage(), browserLanguage()])
          : nmpResolveLanguage(setting)
      }
      const t = nmpCreateTranslator(currentLanguage)

      void runtime.loadStatus()
      const GhostOverlay = createOverlayComponent(react, runtime, t)
      const SettingsSection = createSettingsComponent(react, runtime, t)
      const SettingsIcon = createSettingsIconComponent(react)
      const PanelPage = createPanelComponent(react, SettingsSection)
      // Optional shell service: only used to keep the panel open across a reload.
      const layout = (() => {
        try {
          const service = ctx.get('layout')
          return service !== undefined && service !== null && typeof service.selectPanel === 'function' ? service : null
        } catch {
          return null
        }
      })()
      const panelIsActive = () => {
        try {
          return layout !== null && layout.panelInfo.getSnapshot().activePanelId === PANEL_ID
        } catch {
          return false
        }
      }

      // Language: `t` reads the language when it is called; this only tells the
      // components to render again when it changes (the option was saved, or
      // DSH switched language while the option is "follow DSH").
      ctx.effect(() => {
        let shown = ''
        const check = () => {
          const state = runtime.configStore.getSnapshot()
          if (state.ready === true && state.hostError === '' && state.config.language !== languageMemo) {
            languageMemo = state.config.language
            nmpWriteLanguageMemo(languageMemo)
          }
          const language = currentLanguage()
          if (language === shown) return
          shown = language
          runtime.shellStore.set({ language })
        }
        check()
        const unsubscribe = runtime.configStore.subscribe(check)
        let observer
        try {
          // DSH keeps <html lang> in step with its language.
          observer = new MutationObserver(check)
          observer.observe(document.documentElement, { attributes: true, attributeFilter: ['lang'] })
        } catch {
          observer = undefined
        }
        const timer = setInterval(check, 2000)
        return () => {
          unsubscribe()
          clearInterval(timer)
          try {
            observer?.disconnect()
          } catch {
            /* ignore */
          }
        }
      }, 'next-message-predictor: language')

      // O07: 运行时冲突检测（另一幽灵文字插件存在时让位，设置页显示原因）。
      ctx.effect(() => {
        const detect = () => {
          const conflict = detectGhostConflict(document, window, GHOST_MARKER)
          if (conflict !== null) runtime.noteConflict(conflict.source)
          else runtime.clearConflict()
        }
        detect()
        const timer = setInterval(detect, 2000)
        return () => clearInterval(timer)
      }, 'next-message-predictor: conflict detection')

      // Page-level signals only: focus/blur and tab visibility change whether a
      // suggestion may be painted. Composer-scoped observers live in the overlay.
      ctx.effect(() => {
        const bump = () => runtime.noteDomMutation()
        const onFocusIn = () => bump()
        window.addEventListener('focus', bump)
        window.addEventListener('blur', bump)
        document.addEventListener('visibilitychange', bump)
        document.addEventListener('focusin', onFocusIn, true)
        document.addEventListener('focusout', onFocusIn, true)
        return () => {
          window.removeEventListener('focus', bump)
          window.removeEventListener('blur', bump)
          document.removeEventListener('visibilitychange', bump)
          document.removeEventListener('focusin', onFocusIn, true)
          document.removeEventListener('focusout', onFocusIn, true)
        }
      }, 'next-message-predictor: window signals')

      ctx.effect(
        () =>
          slots.inject('conversation.input.overlay', () =>
            slots.register(
              {
                name: 'conversation.input.overlay',
                id: 'next-message-predictor-ghost',
                order: 100,
                locale: NS,
              },
              GhostOverlay,
            ),
          ),
        'next-message-predictor: overlay',
      )

      // DSH may read a label once, when the entry is registered. When the
      // interface language turns out to be another one afterwards (the Host
      // answered with a different choice, or DSH switched language while the
      // option is "follow DSH"), the entry is registered again.
      const onLanguageChange = (listener) => {
        let shown = t.language()
        return runtime.shellStore.subscribe(() => {
          const next = runtime.shellStore.getSnapshot().language
          if (next === '' || next === shown) return
          shown = next
          listener()
        })
      }

      ctx.effect(() => {
        const register = () =>
          slots.inject('settings.section', () =>
            slots.register(
              {
                name: 'settings.section',
                id: 'next-message-predictor',
                order: 60,
                label: () => t('settings.nav'),
                locale: NS,
              },
              SettingsSection,
            ),
          )
        let dispose = register()
        const unsubscribe = onLanguageChange(() => {
          try {
            dispose()
          } catch {
            /* already released with the plugin */
          }
          dispose = register()
        })
        return () => {
          unsubscribe()
          try {
            dispose()
          } catch {
            /* already released with the plugin */
          }
        }
      }, 'next-message-predictor: settings')
      // Nav icon: DSH renders `settings.section.icon` for a row with `only: <section id>`
      // and falls back to its gear when a plugin registers nothing.
      ctx.effect(
        () =>
          slots.inject('settings.section.icon', () =>
            slots.register({ name: 'settings.section.icon', id: 'next-message-predictor', order: 60 }, SettingsIcon),
          ),
        'next-message-predictor: settings icon',
      )

      // Global panel: the same page as the Settings section, shown in the main
      // area. DSH pairs a `sidebar.panellist` entry with the `main` panel of the
      // same id. The panel stays registered whether or not the sidebar entry is
      // shown, so removing the entry from inside the page does not close it.
      ctx.effect(
        () =>
          slots.inject('main', () => {
            const dispose = slots.register({ name: 'main', key: PANEL_ID, locale: NS }, PanelPage)
            runtime.shellStore.set({ panelAvailable: true })
            // A settings write restarts this plugin, which unregisters the panel
            // and sends the user back to the conversation. Put them back.
            let reopen
            try {
              const leftAt = Number(window[PANEL_REOPEN_KEY])
              delete window[PANEL_REOPEN_KEY]
              if (layout !== null && Number.isFinite(leftAt) && Date.now() - leftAt < PANEL_REOPEN_WINDOW_MS) {
                reopen = setTimeout(() => {
                  try {
                    layout.selectPanel(PANEL_ID)
                  } catch {
                    /* the panel is gone again; nothing to restore */
                  }
                }, 0)
              }
            } catch {
              /* non-browser environment */
            }
            return () => {
              clearTimeout(reopen)
              runtime.shellStore.set({ panelAvailable: false })
              dispose()
            }
          }),
        'next-message-predictor: panel',
      )
      // Registered after the panel: whichever order the two are torn down in,
      // this notices that the panel was open when the plugin went away.
      ctx.effect(() => {
        if (layout === null) return () => {}
        let active = panelIsActive()
        let leftAt = 0
        let unsubscribe = () => {}
        try {
          unsubscribe = layout.panelInfo.subscribe(() => {
            const now = panelIsActive()
            if (active && !now) leftAt = Date.now()
            active = now
          })
        } catch {
          /* no selection source: nothing to remember */
        }
        return () => {
          try {
            unsubscribe()
            if (active || Date.now() - leftAt < 250) window[PANEL_REOPEN_KEY] = Date.now()
          } catch {
            /* ignore */
          }
        }
      }, 'next-message-predictor: panel selection')

      // Left sidebar: is there a panel list at all (Settings only offers the
      // button when there is)...
      ctx.effect(
        () =>
          slots.inject('sidebar.panellist', () => {
            runtime.shellStore.set({ sidebarAvailable: true })
            return () => runtime.shellStore.set({ sidebarAvailable: false })
          }),
        'next-message-predictor: sidebar availability',
      )
      // ...and the entry itself, which follows the `sidebarEntry` option. Until
      // the Host has answered, the last known choice is used so the entry does
      // not pop in late after every page load.
      ctx.effect(() => {
        let disposeEntry
        const sync = () => {
          const state = runtime.configStore.getSnapshot()
          // Host unreachable: the option is unknown, keep the entry as it is.
          if (state.ready === true && state.hostError !== '') return
          const want = state.ready === true ? state.config.sidebarEntry === true : readSidebarEntryMemo()
          if (state.ready === true) writeSidebarEntryMemo(want)
          if (want === (disposeEntry !== undefined)) return
          if (want) {
            try {
              disposeEntry = slots.inject('sidebar.panellist', () =>
                slots.register(
                  { name: 'sidebar.panellist', id: PANEL_ID, order: 60, label: () => t('settings.nav'), locale: NS },
                  SettingsIcon,
                ),
              )
            } catch (error) {
              disposeEntry = undefined
              console.warn('[next-message-predictor] sidebar entry not registered', error)
            }
          } else {
            const dispose = disposeEntry
            disposeEntry = undefined
            try {
              dispose()
            } catch {
              /* already released with the plugin */
            }
          }
        }
        sync()
        const unsubscribe = runtime.configStore.subscribe(sync)
        // Same entry, new label: take it out and put it back.
        const unsubscribeLanguage = onLanguageChange(() => {
          if (disposeEntry === undefined) return
          const dispose = disposeEntry
          disposeEntry = undefined
          try {
            dispose()
          } catch {
            /* already released with the plugin */
          }
          sync()
        })
        return () => {
          unsubscribe()
          unsubscribeLanguage()
          if (disposeEntry !== undefined) {
            const dispose = disposeEntry
            disposeEntry = undefined
            try {
              dispose()
            } catch {
              /* already released with the plugin */
            }
          }
        }
      }, 'next-message-predictor: sidebar entry')

      ctx.effect(
        () => () => {
          runtime.dispose()
          try {
            delete window.__nextMessagePredictor
          } catch {
            /* ignore */
          }
        },
        'next-message-predictor: runtime',
      )

      try {
        window.__nextMessagePredictor = {
          ...runtime.debugApi(),
          version: PLUGIN_VERSION,
          viewId: runtime.getViewId(),
          /** The interface language in use right now (a language id). */
          language: () => t.language(),
          /** Open this plugin's panel in the main area (same as clicking the sidebar entry). */
          openPanel() {
            if (layout === null) return false
            try {
              layout.selectPanel(PANEL_ID)
              return true
            } catch {
              return false
            }
          },
        }
      } catch {
        /* non-browser environment */
      }

      console.info(`[next-message-predictor] client ready v${PLUGIN_VERSION}`)
    },
  }
}

/** Set on `window` when the plugin unloads while its panel is open (value: time). */
const PANEL_REOPEN_KEY = '__nextMessagePredictorPanelReopen'
/** A reload that takes longer than this is not "the same visit" any more. */
const PANEL_REOPEN_WINDOW_MS = 15000

/** Last known `sidebarEntry` choice, so the entry is there before the Host answers. */
const SIDEBAR_ENTRY_MEMO_KEY = 'dsh-next-message-predictor.sidebarEntry'
function readSidebarEntryMemo() {
  try {
    return globalThis.localStorage?.getItem(SIDEBAR_ENTRY_MEMO_KEY) === '1'
  } catch {
    return false
  }
}
function writeSidebarEntryMemo(on) {
  try {
    if (on) globalThis.localStorage?.setItem(SIDEBAR_ENTRY_MEMO_KEY, '1')
    else globalThis.localStorage?.removeItem(SIDEBAR_ENTRY_MEMO_KEY)
  } catch {
    /* storage unavailable: the entry simply appears once the Host answers */
  }
}
